entries[138926] = { ["name"] = "Magistrix Elisande's Coin", ["text"] = "Binds when picked up\n\"I wish to protect my people from the vile outsiders that wish to harm them. Whatever it takes.\"\nSell Price:" }
entries[138927] = { ["name"] = "Oculeth's Vanishing Coin", ["text"] = "Binds when picked up\n\"Oh, to have an apprentice that could keep up with me!\"\nSell Price:" }
entries[138928] = { ["name"] = "Ly'leth Lunastre's Family Crest", ["text"] = "Binds when picked up\n\"I wish my father were alive, to help guide us through these difficult times.\"\nSell Price:" }
entries[138929] = { ["name"] = "Pearlhunter Phin's Soggy Coin", ["text"] = "Binds when picked up\n\"Gloooglrr mrm.\"\nSell Price:" }
entries[138930] = { ["name"] = "Advisor Vandros' Coin", ["text"] = "Binds when picked up\n\"Keep your wishes for yourself. I do not negotiate with fountains.\"\nSell Price:" }
entries[138931] = { ["name"] = "Gul'dan's Coin", ["text"] = "Binds when picked up\n\"I just want all worlds to burn.\"\nSell Price:" }
entries[138932] = { ["name"] = "Yowlon's Mark", ["text"] = "Binds when picked up\n\"I want more kitties.\"\nSell Price:" }
entries[138933] = { ["name"] = "Allari the Souleater's Coin", ["text"] = "Binds when picked up\n\"Fish do not have souls. This is pointless.\"\nSell Price:" }
entries[138934] = { ["name"] = "Altruis the Sufferer's Coin", ["text"] = "Binds when picked up\n\"Think for yourself.\"\nSell Price:" }
