entries[138936] = { ["name"] = "Falara Nightsong's Coin", ["text"] = "Binds when picked up\n\"I remember when Suramar was beautiful and tranquil... before Azshara and her Highborne ruined everything. Wishes will buy you nothing except regret.\"\nSell Price:" }
entries[138937] = { ["name"] = "Izal Whitemoon's Coin", ["text"] = "Binds when picked up\n\"These magi allowed me to land here. While most do nothing but eye you with suspicion and contempt, or worse, some still see past the surface. My wish is for all of us to work together and recognize our true enemy: the Burning Legion.\"\nSell Price:" }
entries[138938] = { ["name"] = "Jace Darkweaver's Coin", ["text"] = "Binds when picked up\n\"In my previous life, I would have loved to have lived in this floating marvel. I would have spent the days fishing in this magic fountain in-between practicing the arcane arts. Those days are long gone.\"\nSell Price:" }
entries[138939] = { ["name"] = "Kayn Sunfury's Coin", ["text"] = "Binds when picked up\n\"Strong leadership and a clear vision are the only path to victory.\"\nSell Price:" }
entries[138940] = { ["name"] = "Kor'vas Bloodthorn's Coin", ["text"] = "Binds when picked up\n\"I don't have the luxury of fishing and wishing. There are demons to kill.\"\nSell Price:" }
entries[138941] = { ["name"] = "The Coin", ["text"] = "Binds when picked up\n\"Gain 1 Mana Crystal this turn only.\"\nSell Price:" }
