entries[138943] = { ["name"] = "Lady Liadrin's Coin", ["text"] = "Binds when picked up\n\"May the Light bathe this land in all its glory.\"\nSell Price:" }
entries[138944] = { ["name"] = "Lunara's Coin", ["text"] = "Binds when picked up\n\"What is nature's call? I actually do wish someone would finally tell me what \"nature's call\" is.\"\nSell Price:" }
entries[138945] = { ["name"] = "Illidan's Coin", ["text"] = "Binds when picked up\n\"An end to the Burning Legion.\"\nSell Price:" }
entries[138946] = { ["name"] = "Queen Azshara's Royal Seal", ["text"] = "Binds when picked up\n\"Soon, you will ALL feel my wrath!!!\"\nSell Price:" }
entries[138947] = { ["name"] = "Gallywix's Coin-on-a-String", ["text"] = "Binds when picked up\n\"Yes! This way I can get my wish AND keep my coin. Hah! Oh no, the string broke! Stupid fountain, give me my coin back...\"\nSell Price:" }
entries[138948] = { ["name"] = "Li Li's Coin", ["text"] = "Binds when picked up\n\"My wish is to never run out of newly-discovered continents to explore.\"\nSell Price:" }
entries[138949] = { ["name"] = "Kirel Narak", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nFeet Leather\n5 Armor\n+4 [Agility or Intellect]\n+6 Stamina\n+ 3 Versatility\n+ 5 Mastery\nDurability 95 / 95\nClasses: Demon Hunter\nEquip: The instant initial damage from your Immolation Aura reduces the remaining cooldown on Fiery Brand by 2 sec for each enemy hit.\n\"Witness the flames that have consumed countless worlds. All will burn in the legion's fire!\"\nSell Price:" }
