entries[139320] = { ["name"] = "Ravaged Seed Pod", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 7 Haste\nUse: Contaminate the ground beneath your feet for 10 sec, dealing 63 Shadow damage to enemies in the area each second. While you remain in this area, you gain 9 Leech. (1 Min Cooldown)\nSell Price:" }
