entries[139322] = { ["name"] = "Cocoon of Enforced Solitude", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+5 Intellect\nUse: Wrap yourself in a cocoon, entering a dreamless sleep for 10 sec. During that time you restore 51 Mana per second. (2 Min Cooldown)\nSell Price:" }
