entries[139324] = { ["name"] = "Goblet of Nightmarish Ichor", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+5 [Agility or Strength]\nEquip: Taking damage has a chance to create a Nightmare Ichor nearby. Absorbing the Ichor increases your Versatility by 19 for 10 sec.\nSell Price:" }
entries[139325] = { ["name"] = "Spontaneous Appendages", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 7 Mastery\nEquip: Your melee attacks have a chance to generate extra appendages for 12 sec that attack nearby enemies for 10 Physical damage every 0.75 sec.\nSell Price:" }
