entries[139436] = { ["name"] = "Glyph of Tattered Wings", ["text"] = "Classes: Demon Hunter\nUse: Permanently teaches you this glyph.\n\nYou now have tattered wings when Glide is active. Exclusive with: Glyph of Fallow Wings Glyph of Fel Wings\nSell Price:" }
entries[139437] = { ["name"] = "Glyph of Fel-Enemies", ["text"] = "Classes: Demon Hunter\nUse: Permanently teaches you this glyph.\n\nYour Spectral Sight is altered by Fel energy causing you to see all enemies in a Fel light.\nSell Price:" }
entries[139438] = { ["name"] = "Glyph of Shadow-Enemies", ["text"] = "Classes: Demon Hunter\nUse: Permanently teaches you this glyph.\n\nYour Spectral Sight is tinted by the void and you see enemies shrouded in Shadow.\nSell Price:" }
entries[139439] = { ["name"] = "The Highkeeper's Ward", ["text"] = "Binds when picked up\nUnique\nOff Hand Shield\n52 Armor\n+2 Strength\n+7 Intellect\n+4 Stamina\n+ 2 Critical Strike\n+ 2 Mastery\nSell Price:" }
entries[139442] = { ["name"] = "Glyph of Burnout", ["text"] = "Classes: Rogue\nUse: Permanently teaches you this glyph.\n\nYour sprint leaves a smoke trail in your wake.\nSell Price:" }
entries[139445] = { ["name"] = "Fel Lexicon", ["text"] = "Quest Item\n\"The tome's black pages are shut with a heavy metal clasp.\"" }
entries[139447] = { ["name"] = "Vial of Pure Light", ["text"] = "Binds when picked up\nUnique\nDuration: 18 hrs\nUse: Summon a Lightspawn to fight alongside you for 10 min.\n\nThe Lightspawn is very durable and will taunt all nearby enemies.\n\nOnly usable on the Broken Isles and Argus.\nSell Price:" }
entries[139448] = { ["name"] = "Vial of Dark Shadows", ["text"] = "Binds when picked up\nUnique\nDuration: 18 hrs\nUse: Summon a Faceless One to fight alongside you for 10 min.\n\nThe Faceless One is very durable and will taunt all nearby enemies.\n\nOnly usable on the Broken Isles and Argus.\nSell Price:" }
entries[139449] = { ["name"] = "Essence of the Naaru", ["text"] = "Binds when picked up\nUnique\nDuration: 18 hrs\nUse: Focus the light of the Naaru to burn all enemies within 15 yards for (2000% of Spell Power) Holy damage two times over 4 sec.\n\nOnly usable on the Broken Isles and Argus.\nSell Price:" }
entries[139450] = { ["name"] = "Void Sphere", ["text"] = "Binds when picked up\nUnique\nDuration: 18 hrs\nUse: Call forth two tendrils from the void to smash all enemies in front of you in a 8 yard area for (2000% of Spell Power) Shadow damage.\n\nOnly usable on the Broken Isles and Argus.\nSell Price:" }
entries[139451] = { ["name"] = "Swirling Void Potion", ["text"] = "Binds when picked up\nUnique\nDuration: 18 hrs\nUse: Drink from the dark potion to surrender your mind to the Void.\n\nFor the next 10 min, you generate 10 Insanity every second.\n\nOnly usable on the Broken Isles and Argus.\nSell Price:" }
entries[139452] = { ["name"] = "Essence of the Light", ["text"] = "Binds when picked up\nUnique\nDuration: 18 hrs\nUse: Release the energy of the Light, causing all party members to heal for 5% of their maximum health every 2 sec.\n\nOnly usable on the Broken Isles and Argus.\nSell Price:" }
entries[139453] = { ["name"] = "Greater Demonic Runestone", ["text"] = "Quest Item\nUnique" }
entries[139457] = { ["name"] = "Odyn's Challenge", ["text"] = "Binds when picked up\nThis Item Begins a Quest\n\"Odyn himself invites the most powerful champions of Azeroth to enter his halls and face his warriors.\"" }
entries[139458] = { ["name"] = "Felbat Toxin Salve", ["text"] = "Quest Item\n\"Counters the toxin that causes a felbat bite to fester and rot.\"" }
entries[139459] = { ["name"] = "Blessing of the Light", ["text"] = "Binds when picked up\nUnique\nDuration: 18 hrs\nUse: Bestows the Blessing of the Light on use. If you should take fatal damage, the Light will restore you to full health and knock back any surrounding enemies.\n\nOnly usable on the Broken Isles and Argus.\nSell Price:" }
entries[139460] = { ["name"] = "Seal of Broken Fate", ["text"] = "\"Twists fate to provide an opportunity for additional treasure in the Emerald Nightmare or the Nighthold.\"" }
entries[139461] = { ["name"] = "Rune of Darkness", ["text"] = "Binds when picked up\nUnique\nDuration: 18 hrs\nUse: Activate the rune to gain a Shroud of Darkness. If you should take fatal damage, the darkness will restore you to full health and knock back any surrounding enemies.\n\nOnly usable on the Broken Isles and Argus.\nSell Price:" }
entries[139463] = { ["name"] = "Felbat Toxin Salve", ["text"] = "Quest Item\nUnique\nUse: Applies a single dose of felbat toxin antidote to your target. (4 Sec Cooldown)\n\"Counters the toxin that causes a felbat bite to fester and rot.\"" }
entries[139464] = { ["name"] = "Lens of the Tides", ["text"] = "Quest Item\nUnique\n\"Through an undocumented ritual, images from the mind can be projected through the lens.\"" }
entries[139465] = { ["name"] = "Flask of Demon Blood", ["text"] = "Quest Item\n\"The liquid bubbles and seethes as if alive.\"" }
entries[139466] = { ["name"] = "Bindings of the Windlord", ["text"] = "Binds when picked up\nUnique\nClasses: Rogue\n\"The left half of a prison intended for Thunderaan the Windlord.\"" }
entries[139467] = { ["name"] = "Satchel of Spoils", ["text"] = "Binds when picked up\n<Right Click to Open>" }
entries[139468] = { ["name"] = "Bindings of the Windlord", ["text"] = "Binds when picked up\nUnique\nClasses: Rogue\n\"The right half of a prison intended for Thunderaan the Windlord.\"" }
