entries[139471] = { ["name"] = "Black Rook Missive", ["text"] = "Binds when picked up\nThis Item Begins a Quest\n\"Lord Ravencrest, the Legion accepts your terms. The reinforcements will arrive as expected. Be sure to honor your side of this agreement.\"" }
entries[139472] = { ["name"] = "Glamorous Party Invitation", ["text"] = "Binds when picked up\nThis Item Begins a Quest\n\"You are cordially invited to the Jeweled Estate, where we will enjoy delectable treats and drinks, and may have a surprise guest...\"" }
entries[139473] = { ["name"] = "Vial of Poisoned Blood", ["text"] = "Binds when picked up\nThis Item Begins a Quest\n\"Blood taken from an unfortunate, corrupted creature within Darkheart Thicket.\"" }
entries[139474] = { ["name"] = "Carved Shell", ["text"] = "Binds when picked up\nThis Item Begins a Quest\n\"Holding it to your ear, you can hear a distant, malevolent voice.\"" }
entries[139475] = { ["name"] = "Waterlogged Letter", ["text"] = "Binds when picked up\nThis Item Begins a Quest\n\"My beloved, I fear that my evil deeds have finally caught up to me, and I face an eternity in the underworld, sailing the seas at the mercy of Helya. Do not forget about me.\"" }
entries[139476] = { ["name"] = "Broken Dragon Scale", ["text"] = "Binds when picked up\nThis Item Begins a Quest\n\"The drogbar kept it in a place of privilege, reminding themselves of the power that Deathwing once had.\"" }
entries[139477] = { ["name"] = "Drained Mana Orb", ["text"] = "Binds when picked up\nThis Item Begins a Quest\n\"Once teeming with energy, the mana from this orb has been completely consumed.\"" }
entries[139478] = { ["name"] = "Broken Warden Helm", ["text"] = "Binds when picked up\nThis Item Begins a Quest\n\"This helm once belonged to a proud Warden. What became of her?\"" }
entries[139479] = { ["name"] = "Broken Portal Shard", ["text"] = "Binds when picked up\nThis Item Begins a Quest\n\"A fragment of a Legion-made portal.\"" }
entries[139480] = { ["name"] = "Corrupted Egg Fragment", ["text"] = "Binds when picked up\nThis Item Begins a Quest\n\"Corruption seeps from it.\"" }
entries[139481] = { ["name"] = "Corrupted Egg Fragment", ["text"] = "Binds when picked up\nThis Item Begins a Quest\n\"Corruption seeps from it.\"" }
