entries[139489] = { ["name"] = "Forgotten Techniques of the Broken Isles", ["text"] = "Binds when picked up\nUse: Re-learn any mining techniques that you learned via questing in the Broken Isles, but forgot after switching professions.\nRequires Legion Mining (1)" }
entries[139490] = { ["name"] = "Forgotten Techniques of the Broken Isles", ["text"] = "Binds when picked up\nUse: Re-learn any skinning techniques that you learned via questing in the Broken Isles, but forgot after switching professions.\nRequires Skinning (1)" }
entries[139491] = { ["name"] = "Forgotten Techniques of the Broken Isles", ["text"] = "Binds when picked up\nUse: Re-learn any herbalism techniques that you learned via questing in the Broken Isles, but forgot after switching professions.\nRequires Legion Herbalism (1)" }
entries[139492] = { ["name"] = "Forgotten Formulas of the Broken Isles", ["text"] = "Binds when picked up\nUse: Re-learn any alchemy formulas that you learned via questing in the Broken Isles, but forgot after switching professions.\nRequires Legion Alchemy (1)" }
entries[139493] = { ["name"] = "Forgotten Plans of the Broken Isles", ["text"] = "Binds when picked up\nUse: Re-learn any blacksmithing plans that you learned via questing in the Broken Isles, but forgot after switching professions.\nRequires Blacksmithing (1)" }
entries[139494] = { ["name"] = "Forgotten Formulas of the Broken Isles", ["text"] = "Binds when picked up\nUse: Re-learn any enchanting formulas that you learned via questing in the Broken Isles, but forgot after switching professions.\nRequires Enchanting (1)" }
entries[139495] = { ["name"] = "Forgotten Schematics of the Broken Isles", ["text"] = "Binds when picked up\nUse: Re-learn any engineering schematics that you learned via questing in the Broken Isles, but forgot after switching professions.\nRequires Engineering (1)" }
entries[139496] = { ["name"] = "Forgotten Techniques of the Broken Isles", ["text"] = "Binds when picked up\nUse: Re-learn any inscription techniques that you learned via questing in the Broken Isles, but forgot after switching professions.\nRequires Inscription (1)" }
entries[139497] = { ["name"] = "Forgotten Designs of the Broken Isles", ["text"] = "Binds when picked up\nUse: Re-learn any jewelcrafting designs that you learned via questing in the Broken Isles, but forgot after switching professions.\nRequires Jewelcrafting (1)" }
entries[139498] = { ["name"] = "Forgotten Patterns of the Broken Isles", ["text"] = "Binds when picked up\nUse: Re-learn any leatherworking patterns that you learned via questing in the Broken Isles, but forgot after switching professions.\nRequires Leatherworking (1)" }
entries[139499] = { ["name"] = "Forgotten Patterns of the Broken Isles", ["text"] = "Binds when picked up\nUse: Re-learn any tailoring patterns that you learned via questing in the Broken Isles, but forgot after switching professions.\nRequires Tailoring (1)" }
entries[139500] = { ["name"] = "Hippogryph Feather", ["text"] = "Binds when picked up\nUnique\nUse: Reduces your fall speed for 20 sec.\nSell Price:" }
entries[139501] = { ["name"] = "Frostcrag Drums", ["text"] = "Quest Item\nUnique\nUse: Bang on the drums to lure Jorhuttam to its feeding area." }
entries[139502] = { ["name"] = "Reins of the Deathcharger", ["text"] = "Binds when picked up\nUnique\nDuration: 1 hour\nUse: Summons and dismisses an Ebon Blade Deathcharger that can be ridden while in combat.\n\nOnly usable on the Broken Isles and Argus.\nSell Price:" }
entries[139503] = { ["name"] = "Bloodtotem Saddle Blanket", ["text"] = "Use: Place a saddle blanket onto your mount, making your mount much more comfortable for 2 hrs.\n\nThe effect's duration is quadrupled for tailors." }
entries[139505] = { ["name"] = "Reins of the Charger", ["text"] = "Binds when picked up\nUnique\nDuration: 1 hour\nUse: Summons and dismisses a Silver Hand Charger that can be ridden while in combat.\n\nOnly usable on the Broken Isles and Argus.\nSell Price:" }
