entries[139536] = { ["name"] = "Emanation of the Winds", ["text"] = "Binds when picked up\nUnique\nClasses: Rogue\nUse: Unlocks the Thunderfury, Hallowed Blade of the Windlord appearance for The Dreadblades .\n\"Secrets of the elemental power held within the famed blade of Thunderaan the Windlord.\"" }
entries[139537] = { ["name"] = "Braid of the Underking", ["text"] = "Quest Item\n\"This magical, shamanic braid has been worn by each of the Underkings since the time of the first days.\"" }
entries[139538] = { ["name"] = "Nightmare Lash", ["text"] = "Quest Item\n\"This whip was formed from the dark energy of Xavius himself.\"" }
entries[139539] = { ["name"] = "Ancient Tideskorn Blade", ["text"] = "Quest Item\n\"The revered weapon of a long-dead Tideskorn warrior.\"" }
entries[139540] = { ["name"] = "Aponi's Journal Page", ["text"] = "Quest Item\n\"Written hastily.\"" }
entries[139541] = { ["name"] = "Sigil of Command", ["text"] = "Quest Item\nUse: Teleport to the demon world of Niskara. (3 Sec Cooldown)\n\"It glows in the presence of the Legion portal.\"" }
entries[139542] = { ["name"] = "Strip of Sailcloth", ["text"] = "Binds when picked up\n\"You doubt even a tailor could use this.\"\nSell Price:" }
entries[139543] = { ["name"] = "Broken Tiller", ["text"] = "Binds when picked up\n\"It could be salvaged by a talented shipwright.\"\nSell Price:" }
entries[139544] = { ["name"] = "Deteriorating Tideskorn War Banner", ["text"] = "Binds when picked up\n\"Once flown proudly on the masts of vrykul longships.\"\nSell Price:" }
entries[139545] = { ["name"] = "Rusted Mariner's Bell", ["text"] = "Binds when picked up\n\"Used to signal other ships though dense fog.\"\nSell Price:" }
entries[139546] = { ["name"] = "Twisting Anima of Souls", ["text"] = "Binds when picked up\nUnique\nClasses: Death Knight\nUse: Unlocks the Touch of Undeath appearance for Maw of the Damned .\n\"A failed experiment in magically stealing the power from the long dead. The resulting mass twists and undulates unsettlingly.\"" }
entries[139547] = { ["name"] = "Runes of the Darkening", ["text"] = "Binds when picked up\nUnique\nClasses: Death Knight\nUse: Unlocks the Dark Runeblade appearance for the Blades of the Fallen Prince .\n\"Written in an ancient language that no living soul remembers, yet somehow the words leap to your tongue, yearning to be read.\"" }
entries[139548] = { ["name"] = "The Bonereaper's Hook", ["text"] = "Binds when picked up\nUnique\nClasses: Death Knight\nUse: Unlocks the Bone Reaper appearance for Apocalypse .\n\"Fed by the steady settling energy of Icecrown Citadel, this crude and brutal weapon could easily be fashioned into an instrument of death.\"" }
entries[139549] = { ["name"] = "Guise of the Deathwalker", ["text"] = "Binds when picked up\nUnique\nClasses: Demon Hunter\nUse: Unlocks the Deathwalker appearance for the Twinblades of the Deceiver .\n\"A dark weapon from a long dead master, hungering to taste blood again.\"" }
entries[139550] = { ["name"] = "Bulwark of the Iron Warden", ["text"] = "Binds when picked up\nUnique\nClasses: Demon Hunter\nUse: Unlocks the Iron Warden appearance for the Aldrachi Warblades .\n\"Once an indomitable construct of the draenei, turned by the Legion into an instrument of destruction, the Iron Warden fell long ago during the taking of the Aldrachi homeworld.\"" }
entries[139551] = { ["name"] = "The Sunbloom", ["text"] = "Binds when picked up\nUnique\nClasses: Druid\nUse: Unlocks the Sunkeeper's Reach appearance for the Scythe of Elune .\n\"A rare flower from the Emerald Dream, not seen in Azeroth since the War of the Ancients.\"" }
entries[139552] = { ["name"] = "Feather of the Moonspirit", ["text"] = "Binds when picked up\nUnique\nClasses: Druid\nUse: Unlocks the Moonspirit appearance for the Fangs of Ashamane .\n\"A single feather from a reclusive wild god. With it, a Druid of the Claw could learn to master a previously unseen form.\"" }
entries[139553] = { ["name"] = "Mark of the Glade Guardian", ["text"] = "Binds when picked up\nUnique\nClasses: Druid\nUse: Unlocks the Guardian of the Glade appearance for the Claws of Ursoc .\n\"A powerful mark put on wild bears by Ursol to empower them as defenders of the wilds in times of need.\"" }
entries[139554] = { ["name"] = "Acorn of the Endless", ["text"] = "Binds when picked up\nUnique\nClasses: Druid\nUse: Unlocks the Warden's Crown appearance for G'Hanir, the Mother Tree .\n\"Several of these magical acorns were saved from one of the oldest trees in the dream before it fell to the Nightmare.\"" }
entries[139555] = { ["name"] = "Designs of the Grand Architect", ["text"] = "Binds when picked up\nUnique\nClasses: Hunter\nUse: Unlocks the Titan's Reach appearance for Titanstrike .\n\"Detailed blueprints on creating a masterwork techno-magical bow using a powerful titan-crafted power-source as its core. How these found their way out of Mimiron's archives is up for speculation.\"\nSell Price:" }
entries[139556] = { ["name"] = "Syriel Crescentfall's Notes: Ravenguard", ["text"] = "Binds when picked up\nUnique\nClasses: Hunter\nUse: Unlocks the Ravenguard appearance for Thas'dorah, Legacy of the Windrunners .\nRequires Court of Farondis\n- Revered\n\"Detailed plans on the construction of an elegant and powerful crossbow, lost to time as the materials to construct it did not exist.\"\nSell Price:" }
entries[139557] = { ["name"] = "Last Breath of the Forest", ["text"] = "Binds when picked up\nUnique\nClasses: Hunter\nUse: Unlocks the Bear's Fortitude appearance for Talonclaw, Spear of the Wild Gods .\n\"Ursoc sacrificed his life for the wilds twice, but he leaves behind a legacy for other noble defenders to uphold in his absence.\"" }
entries[139558] = { ["name"] = "The Woolomancer's Charge", ["text"] = "Binds when picked up\nUnique\nClasses: Mage\nUse: Unlocks the Woolomancer's Charge appearance for Aluneth .\n\"Cote \"Shepherd\" Metcalf was unable to unlock the secrets of this mysterious bleating staff.\"" }
entries[139559] = { ["name"] = "The Stars' Design", ["text"] = "Binds when picked up\nUnique\nClasses: Mage\nUse: Unlocks the Stars' Design appearance for Felo'melorn .\n\"Nightborn designs for a spellblade mirroring a treasured constellation of their people.\"" }
entries[139560] = { ["name"] = "Everburning Crystal", ["text"] = "Binds when picked up\nUnique\nClasses: Mage\nUse: Unlocks the Frostfire Remembrance appearance for Ebonchill .\n\"A frozen crystal lit with an everlasting heatless fire. Safe to touch, it shows no signs of melting.\"" }
entries[139561] = { ["name"] = "Legend of the Monkey King", ["text"] = "Binds when picked up\nUnique\nClasses: Monk\nUse: Unlocks the Ancient Brewkeeper appearance for Fu Zan, the Wanderer's Companion .\n\"A very potent and special brew, said to have been concocted by the Monkey King himself. The keg is exquisite, and might serve other purposes beyond housing brew...\"" }
entries[139562] = { ["name"] = "Breath of the Undying Serpent", ["text"] = "Binds when picked up\nUnique\nClasses: Monk\nUse: Unlocks the Breath of the Undying Serpent appearance for Sheilun, Staff of the Mists .\n\"A swirling font of magical energy, said to originate from the belly of a dragon older than time.\"" }
entries[139563] = { ["name"] = "The Stormfist", ["text"] = "Binds when picked up\nUnique\nClasses: Monk\nUse: Unlocks the Stormfist appearance for the Fists of the Heavens .\n\"Little is known about the creation of the Stormfist, but the power within it seems to originate from both Therazane and Al'Akir, a very unexpected union.\"" }
entries[139564] = { ["name"] = "Lost Edicts of the Watcher", ["text"] = "Binds when picked up\nUnique\nClasses: Paladin\nUse: Unlocks the Watcher's Armament appearance for The Silver Hand .\n\"We have sworn to restore hope to this troubled world. To seek out tyranny and evil wherever they take root... and bring the hammer of justice down upon the wicked.\"" }
entries[139565] = { ["name"] = "Spark of the Fallen Exarch", ["text"] = "Binds when picked up\nUnique\nClasses: Paladin\nUse: Unlocks the Vindicator's Bulwark appearance for Truthguard .\n\"When Exarch Kelios fell, the remaining hope of holding the temple faded away. The Legion had won. The only peace they would find now was in the thought of those few who had escaped, but the Legion would soon take that from them as well.\"" }
entries[139566] = { ["name"] = "Heart of Corruption", ["text"] = "Binds when picked up\nUnique\nClasses: Paladin\nUse: Unlocks the Corrupted Remembrance appearance for Ashbringer .\n\"A grim glimpse at a past that Ashbringer left behind, that many hoped it would never rekindle.\"" }
entries[139567] = { ["name"] = "Writings of the End", ["text"] = "Binds when picked up\nUnique\nClasses: Priest\nUse: Unlocks the Tomekeeper's Spire appearance for Light's Wrath .\n\"Words gathered from the scattered tomes of the Archivist, predicting dire times to come.\"" }
entries[139568] = { ["name"] = "Staff of the Lightborn", ["text"] = "Binds when picked up\nUnique\nClasses: Priest\nUse: Unlocks the Crest of the Lightborn appearance for T'uure, Beacon of the Naaru .\n\"The staff rings peacefully with the power of the Valkyra. The sound comes to rest when touched.\"" }
entries[139569] = { ["name"] = "Claw of N'Zoth", ["text"] = "Binds when picked up\nUnique\nClasses: Priest\nUse: Unlocks the Claw of N'Zoth appearance for Xal'atath, Blade of the Black Empire .\n\"Eyes blinking. Flesh pulsing. It is very much still alive.\"" }
entries[139570] = { ["name"] = "The Cypher of Broken Bone", ["text"] = "Binds when picked up\nUnique\nClasses: Rogue\nUse: Unlocks the Bonebreaker appearance for The Kingslayers .\n\"Secrets of a long-dead assassin known only as \"The Bonebreaker.\" It's rumored that she took up the habit of breaking the leg bones of her slain victims after one of them came back from the dead to seek revenge.\"" }
entries[139571] = { ["name"] = "Tome of Otherworldly Venoms", ["text"] = "Binds when picked up\nUnique\nClasses: Rogue\nUse: Unlocks the Venombite appearance for the Fangs of the Devourer .\n\"A text passed down through generations of Zandalari Shadowhunters, detailing some of the more exotic weapons and venoms they used to slay their enemies.\"" }
entries[139572] = { ["name"] = "Lost Codex of the Amani", ["text"] = "Binds when picked up\nUnique\nClasses: Shaman\nUse: Unlocks the Prestige of the Amani appearance for The Fist of Ra-den .\n\"A long-lost troll text focused on many of the leaders that have risen and fallen over the generations. It spends a particularly long time focusing on a troll named Atai'natha and a powerful magical claw he used to enforce his rule.\"" }
entries[139573] = { ["name"] = "The Warmace of Shirvallah", ["text"] = "Binds when picked up\nUnique\nClasses: Shaman\nUse: Unlocks the Zandalar Champion appearance for Doomhammer .\n\"Despite its ornate frame, this brutal mace claimed many lives in an unbidden attempt to honor the primal god Shirvallah. Long ago, it was lost to the sea with the high priest who wielded it.\"" }
entries[139574] = { ["name"] = "Coil of the Drowned Queen", ["text"] = "Binds when picked up\nUnique\nClasses: Shaman\nUse: Unlocks the Serpent's Coil appearance for Sharas'dal, Scepter of Tides .\n\"Slithering beneath the waves, the Highborne resembled nothing of their previous selves. They were one with the depths now, and servants of something darker beneath...\"" }
entries[139575] = { ["name"] = "Essence of the Executioner", ["text"] = "Binds when picked up\nUnique\nClasses: Warlock\nUse: Unlocks the Fate's End appearance for Ulthalesh, the Deadwind Harvester .\n\"Distilled from the skulls of great champions, this essence offers great power to those willing to pay the dark cost.\"" }
entries[139576] = { ["name"] = "Visage of the First Wakener", ["text"] = "Binds when picked up\nUnique\nClasses: Warlock\nUse: Unlocks the Thal'kiel's Visage appearance for Skull of the Man'ari .\n\"Among the most prominent phrenologists during this period were Thal'kiel and Archimonde. Thal'kiel in particular was noted for having the archetypal sorcerer's skull, for which he was widely admired.\"" }
entries[139577] = { ["name"] = "The Burning Jewel of Sargeras", ["text"] = "Binds when picked up\nUnique\nClasses: Warlock\nUse: Unlocks the Legionterror appearance for Scepter of Sargeras .\n\"A dark thirsting flame burns within the crimson jewel, lapping against the edges as you near.\"" }
entries[139578] = { ["name"] = "The Arcanite Bladebreaker", ["text"] = "Binds when picked up\nUnique\nClasses: Warrior\nUse: Unlocks the Arcanite Bladebreaker appearance for Strom'kar, the Warbreaker .\n\"Hand-crafted by Helgar, master smith of Skyhold, this axe should surpass any steel found on Azeroth.\"" }
entries[139579] = { ["name"] = "The Dragonslayers", ["text"] = "Binds when picked up\nUnique\nClasses: Warrior\nUse: Unlocks the Dragonslayer's Edge appearance for the Warswords of the Valarjar .\n\"Two fearsome axes bearing the skulls of slain dragons, built upon vrykul enchanted runewood. Impressive weaponry by any warrior's standards.\"" }
entries[139580] = { ["name"] = "Burning Plate of the Worldbreaker", ["text"] = "Binds when picked up\nUnique\nClasses: Warrior\nUse: Unlocks the Last Breath of the Worldbreaker appearance for the Scale of the Earth-Warder .\n\"Dark molten blood from Neltharion himself pours along its ridges, left smoldering in his former lair for countless years, waiting to be reunited with a lost scale from the same father.\"" }
entries[139583] = { ["name"] = "Demonic Rune", ["text"] = "Quest Item\n\"Indecipherable characters are engraved upon the stone.\"" }
entries[139584] = { ["name"] = "Sticky Bombs", ["text"] = "Binds when picked up\nUse: Toss a sticky bomb on your target that will detonate after 5 sec, causing (375% of Attack Power) damage to all enemies within 5 yards.\n\nOnly usable on the Broken Isles and Argus. (30 Sec Cooldown)\n15 Charges" }
entries[139585] = { ["name"] = "Smoke Powder", ["text"] = "Binds when picked up\nUse: Throw the Smoke Powder at the ground and disappear in a haze of smoke, causing you to Vanish.\n\nOnly usable on the Broken Isles and Argus.\n10 Charges" }
entries[139586] = { ["name"] = "Thistle Tea", ["text"] = "Binds when picked up\nUse: Restore 100 Energy.\n\nOnly usable in the Broken Isles. (5 Sec Cooldown)\n10 Charges" }
entries[139587] = { ["name"] = "Suspicious Crate", ["text"] = "Binds when picked up\nToy\nClasses: Rogue\nUse: Disguise yourself as a wooden crate. (30 Min Cooldown)" }
entries[139588] = { ["name"] = "Pack of Battle Potions", ["text"] = "Binds when picked up\nUse: Drink a useful battle potion from one of the Uncrowned's personal stash.\n\nOnly usable on the Broken Isles and Argus. (30 Sec Cooldown)\n6 Charges" }
entries[139589] = { ["name"] = "Poisoned Throwing Knives", ["text"] = "Binds when picked up\nUse: Throw a poisoned knife at the target, incapacitating them for 1 min.\n\nOnly usable on the Broken Isles and Argus.\n8 Charges" }
entries[139590] = { ["name"] = "Scroll of Teleport: Ravenholdt", ["text"] = "Binds when picked up\nUse: Teleports you to Ravenholdt Manor. (1 Hour Cooldown)" }
entries[139591] = { ["name"] = "Stolen Tome of Artifact Lore", ["text"] = "Binds when picked up\nSell Price:" }
entries[139592] = { ["name"] = "Smoky Boots", ["text"] = "Binds when picked up\nUse: This gadget seems to improve your speed while stealthed by 15% for 1 hour.\n\nOnly usable on the Broken Isles and Argus.\n3 Charges" }
entries[139593] = { ["name"] = "Sack of Salvaged Goods", ["text"] = "Binds when picked up\nUse: Dig through the salvage to look for hidden treasure. Only available at your Salvage Yard." }
entries[139594] = { ["name"] = "Salvage Crate", ["text"] = "Binds when picked up\nUse: Dig through the salvage to look for hidden treasure. Only available at your Salvage Yard." }
