entries[139599] = { ["name"] = "Empowered Ring of the Kirin Tor", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+4 Stamina\n+ 5 Critical Strike\n+ 9 Mastery\nUse: Teleports the caster to Dalaran. (30 Min Cooldown)\nSell Price:" }
