entries[139631] = { ["name"] = "Vainglorious Draught", ["text"] = "Quest Item\nRequires Court of Farondis\n- Honored\n\"An engraving on the bottle reads: \"May the Light of Lights shine upon our glorious empire for all eternity.\"\"\nSell Price:" }
entries[139632] = { ["name"] = "A Tiny Pair of Goggles", ["text"] = "Binds when picked up\nUnique\nUse: When summoned, Pepe will sometimes be dressed like a traveller." }
