entries[139635] = { ["name"] = "Vantus Rune Technique: Ursoc", ["text"] = "Rank 1\nBinds when picked up\nUnique\nUse: Teaches you how to craft a Vantus Rune: Ursoc.\nCraft a Vantus Rune: Ursoc.\nRequires Legion Inscription (1)\nVantus Rune: Ursoc\nUse: Increase Versatility by 3380 while fighting Ursoc.\n\nYou can only use one Vantus Rune per week, and the effect lasts for the entire week.\nSell Price:\nRequires Sallow Pigment (5), Roseate Pigment (15)" }
