entries[139652] = { ["name"] = "Leyshimmer Blenny", ["text"] = "Binds when picked up\nUse: Toss the fish back into the water, granting 50 Artifact Power to your fishing artifact.\n\"Notoriously shy and difficult to catch.\"\nSell Price:" }
entries[139653] = { ["name"] = "Nar'thalas Hermit", ["text"] = "Binds when picked up\nUse: Toss the fish back into the water, granting 50 Artifact Power to your fishing artifact.\n\"These crabs spend their days hidden beneath the sands of Azsuna's rivers and lagoons.\"\nSell Price:" }
entries[139654] = { ["name"] = "Ghostly Queenfish", ["text"] = "Binds when picked up\nUse: Toss the fish back into the water, granting 50 Artifact Power to your fishing artifact.\n\"A spectre of the queenfish as they once were, ten thousand years ago.\"\nSell Price:" }
entries[139655] = { ["name"] = "Terrorfin", ["text"] = "Binds when picked up\nUse: Toss the fish back into the water, granting 50 Artifact Power to your fishing artifact.\n\"Succumbed to the nightmare that plagues Val'Sharah.\"\nSell Price:" }
entries[139656] = { ["name"] = "Thorned Flounder", ["text"] = "Binds when picked up\nUse: Toss the fish back into the water, granting 50 Artifact Power to your fishing artifact.\n\"Covered with spines, from gill to tail.\"\nSell Price:" }
entries[139657] = { ["name"] = "Ancient Mossgill", ["text"] = "Binds when picked up\nUse: Toss the fish back into the water, granting 50 Artifact Power to your fishing artifact.\n\"The moon-blessed waters of Val'sharah allow the mossgill to grow indefinitely.\"\nSell Price:" }
entries[139658] = { ["name"] = "Mountain Puffer", ["text"] = "Binds when picked up\nUse: Toss the fish back into the water, granting 50 Artifact Power to your fishing artifact.\n\"Revered by the murlocs of Highmountain.\"\nSell Price:" }
entries[139659] = { ["name"] = "Coldriver Carp", ["text"] = "Binds when picked up\nUse: Toss the fish back into the water, granting 50 Artifact Power to your fishing artifact.\n\"This breed detests warmth, preferring the icy waters of snowy Highmountain.\"\nSell Price:" }
entries[139660] = { ["name"] = "Ancient Highmountain Salmon", ["text"] = "Binds when picked up\nUse: Toss the fish back into the water, granting 50 Artifact Power to your fishing artifact.\n\"With the drogbar hunting them so voraciously, Highmountain salmon rarely get this old.\"\nSell Price:" }
entries[139661] = { ["name"] = "Oodelfjisk", ["text"] = "Binds when picked up\nUse: Toss the fish back into the water, granting 50 Artifact Power to your fishing artifact.\n\"The oodelfjisk were fished to extinction long ago.\"\nSell Price:" }
entries[139662] = { ["name"] = "Graybelly Lobster", ["text"] = "Binds when picked up\nUse: Toss the fish back into the water, granting 50 Artifact Power to your fishing artifact.\n\"Attracted to anything shiny.\"\nSell Price:" }
entries[139663] = { ["name"] = "Thundering Stormray", ["text"] = "Binds when picked up\nUse: Toss the fish back into the water, granting 50 Artifact Power to your fishing artifact.\n\"The largest stormrays are the most deadly.\"\nSell Price:" }
entries[139664] = { ["name"] = "Magic-Eater Frog", ["text"] = "Binds when picked up\nUse: Toss the fish back into the water, granting 50 Artifact Power to your fishing artifact.\n\"Much like the nightborne, the frogs of Suramar have developed an insatiable appetite for magic.\"\nSell Price:" }
entries[139665] = { ["name"] = "Seerspine Puffer", ["text"] = "Binds when picked up\nUse: Toss the fish back into the water, granting 50 Artifact Power to your fishing artifact.\n\"On rare occasions, murlocs have been known to use these fish as weapons.\"\nSell Price:" }
entries[139666] = { ["name"] = "Tainted Runescale Koi", ["text"] = "Binds when picked up\nUse: Toss the fish back into the water, granting 50 Artifact Power to your fishing artifact.\n\"The skin of a fish but the heart of a demon. Even the fish are not safe from the Legion.\"\nSell Price:" }
entries[139667] = { ["name"] = "Axefish", ["text"] = "Binds when picked up\nUse: Toss the fish back into the water, granting 50 Artifact Power to your fishing artifact.\n\"Similar to a swordfish, but with a slower attack speed.\"\nSell Price:" }
entries[139668] = { ["name"] = "Seabottom Squid", ["text"] = "Binds when picked up\nUse: Toss the fish back into the water, granting 50 Artifact Power to your fishing artifact.\n\"Cannot be fished, as they never come within a mile of the ocean's surface. These squid must be obtained through... alternative methods.\"\nSell Price:" }
entries[139669] = { ["name"] = "Ancient Black Barracuda", ["text"] = "Binds when picked up\nUse: Toss the fish back into the water, granting 50 Artifact Power to your fishing artifact.\n\"Outside of the notorious whale shark, this is one of the largest fish in the seas of Azeroth.\"\nSell Price:" }
entries[139670] = { ["name"] = "Scream of the Dead", ["text"] = "Binds when picked up\nUnique (5)\nUse: Summon a squad of Valarjar Aspirants to accompany your Champions on missions." }
entries[139671] = { ["name"] = "Deathglare Iris", ["text"] = "Quest Item\n\"It's... looking right at you...\"" }
entries[139672] = { ["name"] = "Horn of the Nightmare Lord", ["text"] = "Quest Item\n\"Touching it fills you with intense rage and hatred.\"" }
entries[139673] = { ["name"] = "Deathlord's Chestguard", ["text"] = "Binds when picked up\nChest Plate\n18 Armor\n+5 [Strength or Intellect]\n+7 Stamina\n+ 3 Critical Strike\n+ 7 Mastery\nDurability 140 / 140\nClasses: Death Knight\nComplete your Class Order Campaign.\n\nDeathlord's Battleplate (0/8)\nDeathlord's Chestguard\nDeathlord's Greatboots\nDeathlord's Gauntlets\nDeathlord's Helm\nDeathlord's Legguards\nDeathlord's Mantle\nDeathlord's Girdle\nDeathlord's Bracers\nLegacy Set: Bonus is inactive\n(2) Set : Increases your out-of-combat regeneration in outdoor Broken Isles zones.\n(4) Set : While you are below 35% health you take 50% reduced damage in outdoor Broken Isles zones.\n(6) Set : Strength increased by 18 .\n(8) Set : Spending a Rune has a chance to increase your Mastery by 71 for 12 sec.\nSell Price:" }
