entries[139767] = { ["name"] = "Robes of the Black Harvest", ["text"] = "Binds when picked up\nChest Cloth\n5 Armor\n+5 Intellect\n+7 Stamina\n+ 6 Critical Strike\n+ 4 Versatility\nDurability 140 / 140\nClasses: Warlock\nComplete your Class Order Campaign.\n\nVestments of the Black Harvest (0/8)\nRobes of the Black Harvest\nPath of the Black Harvest\nGloves of the Black Harvest\nVisage of the Black Harvest\nLeggings of the Black Harvest\nAmice of the Black Harvest\nCinch of the Black Harvest\nWristbands of the Black Harvest\nLegacy Set: Bonus is inactive\n(2) Set : Increases your out-of-combat regeneration in outdoor Broken Isles zones.\n(4) Set : While you are below 35% health you take 50% reduced damage in outdoor Broken Isles zones.\n(6) Set : Intellect increased by 18 .\n(8) Set : Spending a Soul Shard has a chance to increase your Mastery by 71 for 12 sec.\nSell Price:" }
entries[139768] = { ["name"] = "Amice of the Black Harvest", ["text"] = "Binds when picked up\nShoulder Cloth\n3 Armor\n+4 Intellect\n+6 Stamina\n+ 5 Critical Strike\n+ 2 Mastery\nDurability 100 / 100\nClasses: Warlock\nRequires The Nightfallen\n- Exalted\n\nVestments of the Black Harvest (0/8)\nRobes of the Black Harvest\nPath of the Black Harvest\nGloves of the Black Harvest\nVisage of the Black Harvest\nLeggings of the Black Harvest\nAmice of the Black Harvest\nCinch of the Black Harvest\nWristbands of the Black Harvest\nLegacy Set: Bonus is inactive\n(2) Set : Increases your out-of-combat regeneration in outdoor Broken Isles zones.\n(4) Set : While you are below 35% health you take 50% reduced damage in outdoor Broken Isles zones.\n(6) Set : Intellect increased by 18 .\n(8) Set : Spending a Soul Shard has a chance to increase your Mastery by 71 for 12 sec.\nSell Price:" }
entries[139769] = { ["name"] = "Cinch of the Black Harvest", ["text"] = "Binds when picked up\nWaist Cloth\n3 Armor\n+4 Intellect\n+6 Stamina\n+ 3 Critical Strike\n+ 5 Mastery\nDurability 55 / 55\nClasses: Warlock\nObtain every artifact available to your class.\n\nVestments of the Black Harvest (0/8)\nRobes of the Black Harvest\nPath of the Black Harvest\nGloves of the Black Harvest\nVisage of the Black Harvest\nLeggings of the Black Harvest\nAmice of the Black Harvest\nCinch of the Black Harvest\nWristbands of the Black Harvest\nLegacy Set: Bonus is inactive\n(2) Set : Increases your out-of-combat regeneration in outdoor Broken Isles zones.\n(4) Set : While you are below 35% health you take 50% reduced damage in outdoor Broken Isles zones.\n(6) Set : Intellect increased by 18 .\n(8) Set : Spending a Soul Shard has a chance to increase your Mastery by 71 for 12 sec.\nSell Price:" }
entries[139770] = { ["name"] = "Wristbands of the Black Harvest", ["text"] = "Binds when picked up\nWrist Cloth\n2 Armor\n+3 Intellect\n+4 Stamina\n+ 2 Versatility\n+ 4 Mastery\n\nPrismatic Socket\n\nDurability 50 / 50\nClasses: Warlock\nRecruit 6 Champions for your Order Hall.\n\nVestments of the Black Harvest (0/8)\nRobes of the Black Harvest\nPath of the Black Harvest\nGloves of the Black Harvest\nVisage of the Black Harvest\nLeggings of the Black Harvest\nAmice of the Black Harvest\nCinch of the Black Harvest\nWristbands of the Black Harvest\nLegacy Set: Bonus is inactive\n(2) Set : Increases your out-of-combat regeneration in outdoor Broken Isles zones.\n(4) Set : While you are below 35% health you take 50% reduced damage in outdoor Broken Isles zones.\n(6) Set : Intellect increased by 18 .\n(8) Set : Spending a Soul Shard has a chance to increase your Mastery by 71 for 12 sec.\nSell Price:" }
